# ---- mini markdown / drill server ----
def md_inline(s):
    s=html.escape(s)
    s=re.sub(r'!\[\]\(([^)]+)\)', r'<img src="/media/\1">', s)
    s=re.sub(r'_([^_]+)_', r'<em>\1</em>', s)
    return s

def render_md(s):
    if not s: return ''
    parts=s.split('\n\n')
    out=[]
    for p in parts:
        lines=p.split('\n')
        if all(l.startswith('- ') for l in lines if l):
            out.append('<ul>' + ''.join('<li>'+md_inline(l[2:])+'</li>' for l in lines if l) + '</ul>')
        elif p.startswith('$$'):
            out.append('<p>'+md_inline(p)+'</p>')
        else:
            out.append('<p>'+md_inline(p).replace('\n','<br>')+'</p>')
    return ''.join(x+'\n' for x in out)

def html_page(card, revealed=False, progress=0, done=False, answer_controls='full'):
    head='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>hashcards</title><link rel="stylesheet" href="/katex/katex.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css"><script defer src="/katex/katex.js"></script><script defer src="/katex/mhchem.js"></script><script defer src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js"></script><link rel="stylesheet" href="/style.css"><style>.card-content { opacity: 0; }</style><noscript><style>.card-content { opacity: 1; }</style></noscript></head><body>'
    if done or not card:
