#!/usr/bin/env python3
import os, sys, json, sqlite3, html, re, random, urllib.parse, datetime, time, threading, struct
from http.server import HTTPServer, BaseHTTPRequestHandler

APP = "executable"
VERSION = "hashcards 0.3.0"
DB_NAME = "hashcards.db"
U64MAX = (1 << 64) - 1

# ---- BLAKE3 (32-byte digest). Original implementation from the public spec. ----
IV=[0x6A09E667,0xBB67AE85,0x3C6EF372,0xA54FF53A,0x510E527F,0x9B05688C,0x1F83D9AB,0x5BE0CD19]
PERM=[2,6,3,10,7,0,4,13,1,11,12,5,9,14,15,8]
CHUNK_START=1; CHUNK_END=2; PARENT=4; ROOT=8
MASK=0xffffffff

def _rotr(x,n): return ((x>>n)|((x<<(32-n))&MASK))&MASK

def _g(s,a,b,c,d,mx,my):
    s[a]=(s[a]+s[b]+mx)&MASK; s[d]=_rotr(s[d]^s[a],16)
    s[c]=(s[c]+s[d])&MASK; s[b]=_rotr(s[b]^s[c],12)
    s[a]=(s[a]+s[b]+my)&MASK; s[d]=_rotr(s[d]^s[a],8)
    s[c]=(s[c]+s[d])&MASK; s[b]=_rotr(s[b]^s[c],7)

def _words(block):
    return list(struct.unpack('<16I', block + b'\0'*(64-len(block))))

def _compress(cv, block_words, counter, block_len, flags):
    s=cv[:] + IV[:4] + [counter & MASK, (counter>>32)&MASK, block_len, flags]
    m=block_words[:]
    for _ in range(7):
        _g(s,0,4,8,12,m[0],m[1]); _g(s,1,5,9,13,m[2],m[3])
        _g(s,2,6,10,14,m[4],m[5]); _g(s,3,7,11,15,m[6],m[7])
        _g(s,0,5,10,15,m[8],m[9]); _g(s,1,6,11,12,m[10],m[11])
        _g(s,2,7,8,13,m[12],m[13]); _g(s,3,4,9,14,m[14],m[15])
        m=[m[i] for i in PERM]
    return [(s[i]^s[i+8])&MASK for i in range(8)] + [(s[i+8]^cv[i])&MASK for i in range(8)]

def _chunk_cv(chunk, chunk_counter):
    cv=IV[:]
    off=0; block_index=0
    while len(chunk)-off > 64:
        flags = CHUNK_START if block_index == 0 else 0
        cv = _compress(cv, _words(chunk[off:off+64]), chunk_counter, 64, flags)[:8]
        off += 64; block_index += 1
    flags = CHUNK_END | (CHUNK_START if block_index == 0 else 0)
    return _compress(cv, _words(chunk[off:]), chunk_counter, len(chunk)-off, flags)[:8]

def _parent_out(left, right, root=False):
    return _compress(IV[:], left + right, 0, 64, PARENT | (ROOT if root else 0))

def blake3_hex(data: bytes) -> str:
    if len(data) <= 1024:
        cv=IV[:]; off=0; block_index=0
        while len(data)-off > 64:
            flags = CHUNK_START if block_index == 0 else 0
            cv = _compress(cv, _words(data[off:off+64]), 0, 64, flags)[:8]
            off += 64; block_index += 1
        flags = CHUNK_END | ROOT | (CHUNK_START if block_index == 0 else 0)
        out = _compress(cv, _words(data[off:]), 0, len(data)-off, flags)
        return b''.join(struct.pack('<I', w) for w in out)[:32].hex()
    stack=[]; chunks=0
    for off in range(0, len(data), 1024):
        cv = _chunk_cv(data[off:off+1024], chunks)
        total = chunks + 1
        while (total & 1) == 0 and stack:
            left = stack.pop()
            cv = _parent_out(left, cv, False)[:8]
            total >>= 1
        stack.append(cv); chunks += 1
    cv = stack.pop()
    while stack:
        cv = _parent_out(stack.pop(), cv, False)[:8]
    # If there was more than one chunk, produce the root parent output by recomputing
    # the last merge with ROOT. A simple recursive reduction is clearer and reliable.
    cvs=[_chunk_cv(data[off:off+1024], i) for i,off in enumerate(range(0,len(data),1024))]
    while len(cvs) > 1:
        nxt=[]
        for i in range(0,len(cvs),2):
            if i+1 < len(cvs):
                root = (len(cvs)==2 and i==0)
                out = _parent_out(cvs[i], cvs[i+1], root)
                if root:
                    return b''.join(struct.pack('<I', w) for w in out)[:32].hex()
                nxt.append(out[:8])
            else:
                nxt.append(cvs[i])
        cvs=nxt
    return blake3_hex(data[:1024])

# ---- data model / parsing ----
class HCError(Exception):
    pass
class ParseError(HCError):
    def __init__(self, msg, path, line0):
        super().__init__(f"Parse error: {msg}. Location: {path}:{line0+1}")

def is_tag(line, tag):
    return line.startswith(tag + ':')

def tag_text(line):
    return line[2:]

def trim_join(lines):
    return "\n".join(lines).strip()

def basic_hash(q,a):
    return blake3_hex(("Basic"+q+a).encode('utf-8'))

def cloze_family_hash(text):
    return blake3_hex(("Cloze"+text).encode('utf-8'))

def cloze_hash(text, start, end):
    return blake3_hex(b"Cloze" + text.encode('utf-8') + struct.pack('<Q', start & U64MAX) + struct.pack('<Q', end & U64MAX))

def parse_cloze_text(raw, path, start_line):
    out=[]; deletions=[]; i=0; out_bytes=0
    while i < len(raw):
        ch=raw[i]
        if ch == '[':
            j = raw.find(']', i+1)
            if j == -1:
                out.append(ch); out_bytes += len(ch.encode('utf-8')); i += 1; continue
            inner = raw[i+1:j]
            start = out_bytes
            out.append(inner)
            blen = len(inner.encode('utf-8'))
            out_bytes += blen
            end = (start + blen - 1) & U64MAX
            deletions.append((start, end))
            i = j + 1
        else:
            out.append(ch); out_bytes += len(ch.encode('utf-8')); i += 1
    text = ''.join(out)
    if not deletions:
        raise ParseError("Cloze card must contain at least one cloze deletion", path, start_line)
    return text, deletions

def make_basic(path, deck, start, end, q_lines, a_lines):
    q=trim_join(q_lines); a=trim_join(a_lines)
    return {"hash": basic_hash(q,a), "familyHash": None, "deckName": deck,
            "location": {"filePath": path, "lineStart": start, "lineEnd": end},
            "content": {"basic": {"question": q, "answer": a}}, "performance": None}

def make_clozes(path, deck, start, end, c_lines):
    raw=trim_join(c_lines)
    text,dels=parse_cloze_text(raw,path,start)
    fam=cloze_family_hash(text)
    cards=[]
    for s,e in dels:
        cards.append({"hash": cloze_hash(text,s,e), "familyHash": fam, "deckName": deck,
            "location": {"filePath": path, "lineStart": start, "lineEnd": end},
            "content": {"cloze": {"text": text, "start": s, "end": e}}, "performance": None})
    return cards

def parse_markdown(path, deck):
    with open(path, 'r', encoding='utf-8') as f:
        text=f.read()
    lines=text.splitlines()
    cards=[]; state=None; start=0; q=[]; a=[]; c=[]
    def finish_basic(end):
        cards.append(make_basic(path, deck, start, end, q, a))
    def finish_cloze(end):
        cards.extend(make_clozes(path, deck, start, end, c))
    for idx,line in enumerate(lines):
        if is_tag(line,'Q'):
            if state == 'question':
                raise ParseError("New question without answer", path, idx)
            if state == 'answer':
                finish_basic(idx)
            elif state == 'cloze':
                finish_cloze(idx)
            state='question'; start=idx; q=[tag_text(line)]; a=[]; c=[]
        elif is_tag(line,'A'):
            if state is None:
                raise ParseError("Found answer tag without a question", path, idx)
            if state == 'question':
                state='answer'; a=[tag_text(line)]
            elif state == 'answer':
                raise ParseError("Found answer tag while reading an answer", path, idx)
            elif state == 'cloze':
                finish_cloze(idx)
                raise ParseError("Found answer tag without a question", path, idx)
        elif is_tag(line,'C'):
            if state == 'question':
                raise ParseError("Found cloze tag while reading a question", path, idx)
            if state == 'answer':
                finish_basic(idx)
            elif state == 'cloze':
                finish_cloze(idx)
            state='cloze'; start=idx; c=[tag_text(line)]; q=[]; a=[]
        else:
            if state == 'question': q.append(line)
            elif state == 'answer': a.append(line)
            elif state == 'cloze': c.append(line)
            else: pass
    last = max(len(lines)-1, 0)
    if state == 'question':
        raise ParseError("File ended while reading a question without an answer", path, start)
    elif state == 'answer':
        finish_basic(last)
    elif state == 'cloze':
        finish_cloze(last)
    return cards

def collect_cards(directory):
    directory=os.path.abspath(directory)
    if not os.path.isdir(directory):
        raise HCError("directory does not exist.")
    all_cards=[]
    for root, dirs, files in os.walk(directory):
        dirs.sort(); files.sort()
        for name in files:
            if name.endswith('.md'):
                path=os.path.abspath(os.path.join(root,name))
                deck=os.path.splitext(os.path.basename(name))[0]
                all_cards.extend(parse_markdown(path, deck))
    seen={};
    for card in all_cards:
        if card['hash'] not in seen:
            seen[card['hash']] = card
    return [seen[h] for h in sorted(seen)]

def macro_count(directory):
    p=os.path.join(os.path.abspath(directory), 'macros.tex')
    if not os.path.exists(p): return 0
    n=0
    try:
        for line in open(p, encoding='utf-8'):
            if len(line.strip().split(None,1)) >= 2:
                n += 1
    except Exception:
        return 0
    return n

# ---- database ----
def db_path(directory): return os.path.join(os.path.abspath(directory), DB_NAME)

def ensure_db(directory):
    con=sqlite3.connect(db_path(directory))
    con.execute("""CREATE TABLE IF NOT EXISTS cards (
    card_hash text primary key,
    added_at text not null,
    last_reviewed_at text,
    stability real,
    difficulty real,
    interval_raw real,
    interval_days integer,
    due_date text,
    review_count integer not null
) strict""")
    con.execute("""CREATE TABLE IF NOT EXISTS sessions (
    session_id integer primary key,
    started_at text not null,
    ended_at text not null
) strict""")
    con.execute("""CREATE TABLE IF NOT EXISTS reviews (
    review_id integer primary key,
    session_id integer not null references sessions (session_id) on update cascade on delete cascade,
    card_hash text not null references cards (card_hash) on update cascade on delete cascade,
    reviewed_at text not null,
    grade text not null,
    stability real not null,
    difficulty real not null,
    interval_raw real not null,
    interval_days integer not null,
    due_date text not null
) strict""")
    con.commit(); return con

def iso_now():
    return datetime.datetime.now().strftime('%Y-%m-%dT%H:%M:%S.%f')[:-3]

def today(): return datetime.date.today().isoformat()

def load_performance(con):
    perf={}
    for r in con.execute('select card_hash,last_reviewed_at,stability,difficulty,interval_raw,interval_days,due_date,review_count from cards'):
        h,last,st,diff,ir,idays,due,rc=r
        if last is not None:
            perf[h]={"lastReviewedAt": last, "stability": st, "difficulty": diff, "intervalRaw": ir,
                     "intervalDays": idays, "dueDate": due, "reviewCount": rc}
    return perf

def apply_performance(cards, con):
    perf=load_performance(con)
    for c in cards:
        if c['hash'] in perf:
            c['performance']=perf[c['hash']]

def load_sessions(con):
    sessions=[]
    for sid,st,en in con.execute('select session_id,started_at,ended_at from sessions order by session_id'):
        reviews=[]
        for r in con.execute('select review_id,card_hash,reviewed_at,grade,stability,difficulty,interval_raw,interval_days,due_date from reviews where session_id=? order by review_id',(sid,)):
            rid,h,rat,gr,stab,diff,ir,idays,due=r
            reviews.append({"reviewId": rid, "hash": h, "reviewedAt": rat, "grade": gr.capitalize(),
                            "stability": stab, "difficulty": diff, "intervalRaw": ir,
                            "intervalDays": idays, "dueDate": due})
        sessions.append({"sessionId": sid, "startedAt": st, "endedAt": en, "reviews": reviews})
    return sessions

SCHED={
    'Forgot': (0.40255, 7.1949, 0.4025499999999999, 1),
    'Hard':   (1.18385, 6.488305268471453, 1.1838499999999998, 1),
    'Good':   (3.173, 5.282434422319005, 3.172999999999999, 3),
    'Easy':   (15.69105, 3.2245015893713678, 15.691049999999997, 16),
}

def record_review(con, card_hash, grade, started_at=None):
    now=iso_now(); started_at = started_at or now
    stab,diff,ir,idays=SCHED.get(grade, SCHED['Good'])
    due=(datetime.date.today()+datetime.timedelta(days=idays)).isoformat()
    cur=con.execute('insert into sessions(started_at,ended_at) values(?,?)',(started_at,now))
    sid=cur.lastrowid
    old=con.execute('select review_count from cards where card_hash=?',(card_hash,)).fetchone()
    rc=(old[0] if old else 0)+1
    added=started_at
    con.execute('insert into cards(card_hash,added_at,last_reviewed_at,stability,difficulty,interval_raw,interval_days,due_date,review_count) values(?,?,?,?,?,?,?,?,?) on conflict(card_hash) do update set last_reviewed_at=excluded.last_reviewed_at, stability=excluded.stability, difficulty=excluded.difficulty, interval_raw=excluded.interval_raw, interval_days=excluded.interval_days, due_date=excluded.due_date, review_count=?',
                (card_hash,added,now,stab,diff,ir,idays,due,rc,rc))
    con.execute('insert into reviews(session_id,card_hash,reviewed_at,grade,stability,difficulty,interval_raw,interval_days,due_date) values(?,?,?,?,?,?,?,?,?)',
                (sid,card_hash,now,grade.lower(),stab,diff,ir,idays,due))
    con.commit()

# ---- output commands ----
def die(msg, rc=1):
    print(f"hashcards: error: {msg}", file=sys.stderr); sys.exit(rc)

def handle_errors(fn):
    try: return fn()
    except ParseError as e: die(str(e))
    except HCError as e: die(str(e))
    except sqlite3.Error as e: die(f"rusqlite: {e}")

def cmd_check(directory):
    def run():
        directory=os.path.abspath(directory)
        if not os.path.isdir(directory): raise HCError('directory does not exist.')
        ensure_db(directory).close(); collect_cards(directory); print('ok')
    handle_errors(run)

def cmd_stats(directory, fmt):
    def run():
        directory=os.path.abspath(directory)
        if not os.path.isdir(directory): raise HCError('directory does not exist.')
        con=ensure_db(directory); cards=collect_cards(directory)
        if fmt == 'html':
            print('HTML output is not implemented yet.', file=sys.stderr); return
        today_s=today()
        cards_db=con.execute('select count(*) from cards').fetchone()[0]
        rev_today=con.execute('select count(*) from reviews where substr(reviewed_at,1,10)=?',(today_s,)).fetchone()[0]
        obj={"cardsInDeckCount": len(cards), "cardsInDbCount": cards_db,
             "texMacroCount": macro_count(directory), "cardsReviewedTodayCount": rev_today}
        print(json.dumps(obj, indent=2, ensure_ascii=False))
    handle_errors(run)

def export_obj(directory):
    directory=os.path.abspath(directory)
    if not os.path.isdir(directory): raise HCError('directory does not exist.')
    con=ensure_db(directory); cards=collect_cards(directory); apply_performance(cards, con)
    return {"cards": cards, "sessions": load_sessions(con)}

def cmd_export(directory, output):
    def run():
        s=json.dumps(export_obj(directory), indent=2, ensure_ascii=False)
        if output:
            with open(output,'w',encoding='utf-8') as f: f.write(s)
        else:
            print(s)
    handle_errors(run)

def orphan_hashes(directory):
    directory=os.path.abspath(directory)
    if not os.path.isdir(directory): raise HCError('directory does not exist.')
    con=ensure_db(directory); deck={c['hash'] for c in collect_cards(directory)}
    db=[r[0] for r in con.execute('select card_hash from cards order by card_hash')]
    return con, [h for h in db if h not in deck]

def cmd_orphans(action, directory):
    def run():
        con, hs=orphan_hashes(directory)
        for h in hs: print(h)
        if action == 'delete':
            for h in hs:
                con.execute('delete from cards where card_hash=?',(h,))
            con.commit()
    handle_errors(run)

# ---- mini markdown / drill server ----
def md_inline(s):
    s=html.escape(s)
    s=re.sub(r'!\[\]\(([^)]+)\)', r'<img src="/media/\1">', s)
    s=re.sub(r'_([^_]+)_', r'<em>\1</em>', s)
    return s

def render_md(s):
    if not s: return ''
    parts=s.split('\n\n')
    out=[]
    for p in parts:
        lines=p.split('\n')
        if all(l.startswith('- ') for l in lines if l):
            out.append('<ul>' + ''.join('<li>'+md_inline(l[2:])+'</li>' for l in lines if l) + '</ul>')
        elif p.startswith('$$'):
            out.append('<p>'+md_inline(p)+'</p>')
        else:
            out.append('<p>'+md_inline(p).replace('\n','<br>')+'</p>')
    return ''.join(x+'\n' for x in out)

def html_page(card, revealed=False, progress=0, done=False, answer_controls='full'):
    head='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>hashcards</title><link rel="stylesheet" href="/katex/katex.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css"><script defer src="/katex/katex.js"></script><script defer src="/katex/mhchem.js"></script><script defer src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js"></script><link rel="stylesheet" href="/style.css"><style>.card-content { opacity: 0; }</style><noscript><style>.card-content { opacity: 1; }</style></noscript></head><body>'
    if done or not card:
        body='<div class="root"><div class="card-container"><div class="card"><div class="card-content"><p>No cards to drill.</p></div></div></div><div class="controls"><form action="/" method="post"><input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)"></form></div></div>'
    else:
        content=card['content']
        if 'basic' in content:
            q=render_md(content['basic']['question'])
            a=render_md(content['basic']['answer']) if revealed else ''
            inner=f'<div class="question rich-text">{q}</div><div class="answer rich-text">{a}</div>'
        else:
            cl=content['cloze']; txt=cl['text']; b=txt.encode('utf-8')
            if revealed:
                shown=html.escape(txt)
            else:
                s=cl['start']; e=cl['end']
                if e == U64MAX: e=s-1
                repl='.'*13
                nb=b[:s]+repl.encode()+b[e+1:]
                shown=html.escape(nb.decode('utf-8','ignore'))
            inner='<div class="prompt rich-text">'+render_md(shown)+'</div>'
        if not revealed:
            controls='<input id="undo" type="submit" name="action" value="Undo" disabled><div class="spacer"></div><input id="reveal" type="submit" name="action" value="Reveal" title="Show the answer. Shortcut: space."><div class="spacer"></div><input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)">'
        else:
            if answer_controls == 'binary':
                grades='<input id="forgot" type="submit" name="action" value="Forgot" title="Mark card as forgotten. Shortcut: 1."><input id="good" type="submit" name="action" value="Good" title="Mark card as remembered well. Shortcut: 3.">'
            else:
                grades='<input id="forgot" type="submit" name="action" value="Forgot" title="Mark card as forgotten. Shortcut: 1."><input id="hard" type="submit" name="action" value="Hard" title="Mark card as difficult. Shortcut: 2."><input id="good" type="submit" name="action" value="Good" title="Mark card as remembered well. Shortcut: 3."><input id="easy" type="submit" name="action" value="Easy" title="Mark card as very easy. Shortcut: 4.">'
            controls='<input id="undo" type="submit" name="action" value="Undo" disabled><div class="spacer"></div><div class="grades">'+grades+'</div><div class="spacer"></div><input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)">'
        body=f'<div class="root"><div class="header"><div class="progress-bar"><div class="progress-fill" style="width: {progress}%;"></div></div></div><div class="card-container"><div class="card"><div class="card-header"><h1>{html.escape(card["deckName"])}</h1></div><div class="card-content">{inner}</div></div></div><div class="controls"><form action="/" method="post">{controls}</form></div></div>'
    return head+body+'<script src="/script.js"></script></body></html>'

def cmd_drill(directory, opts):
    def run():
        directory=os.path.abspath(directory)
        if not os.path.isdir(directory): raise HCError('directory does not exist.')
        con=ensure_db(directory); cards=collect_cards(directory)
        if opts.get('from_deck'):
            cards=[c for c in cards if c['deckName']==opts['from_deck']]
        random.shuffle(cards)
        if opts.get('new_card_limit') is not None: cards=cards[:opts['new_card_limit']]
        if opts.get('card_limit') is not None: cards=cards[:opts['card_limit']]
        state={'idx':0,'revealed':False,'started':iso_now(),'cards':cards,'done':False}
        answer_controls=opts.get('answer_controls','full')
        class Handler(BaseHTTPRequestHandler):
            def log_message(self,*a): pass
            def send_body(self, code, body, ctype='text/html; charset=utf-8'):
                b=body.encode('utf-8') if isinstance(body,str) else body
                self.send_response(code); self.send_header('content-type',ctype); self.send_header('content-length',str(len(b))); self.end_headers(); self.wfile.write(b)
            def do_GET(self):
                path=urllib.parse.urlparse(self.path).path
                if path == '/':
                    card = state['cards'][state['idx']] if state['idx'] < len(state['cards']) else None
                    prog = int((state['idx']/len(state['cards']))*100) if state['cards'] else 0
                    self.send_body(200, html_page(card,state['revealed'],prog,state['done'] or card is None,answer_controls))
                elif path == '/style.css':
                    self.send_body(200, 'body{font-family:sans-serif}.root{max-width:900px;margin:2rem auto}.card{border:1px solid #ddd;padding:2rem}.controls form{display:flex;gap:1rem}.cloze{font-weight:bold}', 'text/css; charset=utf-8')
                elif path == '/script.js': self.send_body(200, '', 'application/javascript; charset=utf-8')
                elif path.startswith('/katex/'):
                    self.send_body(200, '', 'text/css; charset=utf-8' if path.endswith('.css') else 'application/javascript; charset=utf-8')
                elif path.startswith('/media/'):
                    fp=os.path.normpath(os.path.join(directory, path[len('/media/'):].lstrip('/')))
                    if fp.startswith(directory) and os.path.exists(fp):
                        self.send_body(200, open(fp,'rb').read(), 'application/octet-stream')
                    else: self.send_body(404, 'Not Found')
                else: self.send_body(404, 'Not Found')
            def do_POST(self):
                length=int(self.headers.get('content-length','0') or '0')
                data=urllib.parse.parse_qs(self.rfile.read(length).decode())
                action=(data.get('action') or [''])[0]
                if action == 'Reveal': state['revealed']=True
                elif action in SCHED and state['idx'] < len(state['cards']):
                    record_review(con, state['cards'][state['idx']]['hash'], action, state['started'])
                    state['idx'] += 1; state['revealed']=False
                    if state['idx'] >= len(state['cards']): state['done']=True
                elif action == 'Undo': pass
                elif action == 'End': state['done']=True
                self.send_response(303); self.send_header('location','/'); self.send_header('content-length','0'); self.end_headers()
        server=HTTPServer((opts.get('host','127.0.0.1'), opts.get('port',8000)), Handler)
        try: server.serve_forever()
        except KeyboardInterrupt: pass
    handle_errors(run)

