def orphan_sub_help(name):
    desc='List the hashes of all orphan cards in the collection' if name=='list' else 'Remove all orphan cards from the database'
    return f"""{desc}

Usage: executable orphans {name} [DIRECTORY]

Arguments:
  [DIRECTORY]  Path to the collection directory. By default, the current working directory is used

Options:
  -h, --help  Print help"""

def parse_value(args, i, opt):
    if args[i].startswith(opt+'='): return args[i].split('=',1)[1], i
    if i+1 >= len(args):
        print(f"error: a value is required for '{opt} <{opt[2:].replace('-', '_').upper()}>'", file=sys.stderr); sys.exit(2)
    return args[i+1], i+1

def main(argv):
    if not argv:
        print(TOP_HELP, file=sys.stderr); return 2
    if argv[0] in ('-h','--help'):
        print(TOP_HELP); return 0
    if argv[0] in ('-V','--version'):
        print(VERSION); return 0
    if argv[0] == 'help':
        if len(argv)==1: print(TOP_HELP); return 0
        m={'drill':DRILL_HELP,'stats':STATS_HELP,'check':CHECK_HELP,'export':EXPORT_HELP,'orphans':ORPHANS_HELP}
        if argv[1]=='orphans' and len(argv)>2 and argv[2] in ('list','delete'):
            print(orphan_sub_help(argv[2])); return 0
        print(m.get(argv[1], TOP_HELP)); return 0
    cmd=argv[0]; args=argv[1:]
    if cmd == 'check':
        if args and args[0] in ('-h','--help'): print(CHECK_HELP); return 0
        cmd_check(args[0] if args else os.getcwd()); return 0
    if cmd == 'stats':
        if args and args[0] in ('-h','--help'): print(STATS_HELP); return 0
        fmt='html'; directory=None; i=0
        while i < len(args):
            if args[i].startswith('--format'):
                val,i=parse_value(args,i,'--format')
                if val not in ('html','json'):
                    print(f"error: invalid value '{val}' for '--format <FORMAT>'\n  [possible values: html, json]" + ("\n\n  tip: a similar value exists: 'html'" if val=='xml' else '') + "\n\nFor more information, try '--help'.", file=sys.stderr); return 2
                fmt=val
            else: directory=args[i]
            i+=1
        cmd_stats(directory or os.getcwd(),fmt); return 0
    if cmd == 'export':
        if args and args[0] in ('-h','--help'): print(EXPORT_HELP); return 0
        output=None; directory=None; i=0
        while i < len(args):
            if args[i].startswith('--output'):
                output,i=parse_value(args,i,'--output')
            else: directory=args[i]
            i+=1
        cmd_export(directory or os.getcwd(), output); return 0
    if cmd == 'orphans':
        if not args:
            print(ORPHANS_HELP, file=sys.stderr); return 2
        if args[0] in ('-h','--help'): print(ORPHANS_HELP); return 0
        if args[0] == 'help':
            if len(args)>1 and args[1] in ('list','delete'): print(orphan_sub_help(args[1]))
            else: print(ORPHANS_HELP)
            return 0
        if args[0] not in ('list','delete'):
            print(f"error: unrecognized subcommand '{args[0]}'\n\nUsage: executable orphans <COMMAND>\n\nFor more information, try '--help'.", file=sys.stderr); return 2
        action=args[0]; rest=args[1:]
        if rest and rest[0] in ('-h','--help'): print(orphan_sub_help(action)); return 0
        cmd_orphans(action, rest[0] if rest else os.getcwd()); return 0
    if cmd == 'drill':
        if args and args[0] in ('-h','--help'): print(DRILL_HELP); return 0
        opts={'host':'127.0.0.1','port':8000,'answer_controls':'full'}; directory=None; i=0
        while i < len(args):
            a=args[i]
            if a.startswith('--card-limit'):
                v,i=parse_value(args,i,'--card-limit')
                try: opts['card_limit']=int(v)
                except ValueError:
                    print(f"error: invalid value '{v}' for '--card-limit <CARD_LIMIT>': invalid digit found in string\n\nFor more information, try '--help'.", file=sys.stderr); return 2
            elif a.startswith('--new-card-limit'):
                v,i=parse_value(args,i,'--new-card-limit'); opts['new_card_limit']=int(v)
            elif a.startswith('--host'):
                v,i=parse_value(args,i,'--host'); opts['host']=v
            elif a.startswith('--port'):
                v,i=parse_value(args,i,'--port'); opts['port']=int(v)
            elif a.startswith('--from-deck'):
                v,i=parse_value(args,i,'--from-deck'); opts['from_deck']=v
            elif a.startswith('--open-browser'):
                v,i=parse_value(args,i,'--open-browser')
                if v not in ('true','false'):
                    print(f"error: invalid value '{v}' for '--open-browser <OPEN_BROWSER>'\n  [possible values: true, false]\n\nFor more information, try '--help'.", file=sys.stderr); return 2
            elif a.startswith('--answer-controls'):
                v,i=parse_value(args,i,'--answer-controls')
                if v not in ('full','binary'):
                    print(f"error: invalid value '{v}' for '--answer-controls <ANSWER_CONTROLS>'\n  [possible values: full, binary]\n\nFor more information, try '--help'.", file=sys.stderr); return 2
                opts['answer_controls']=v
            elif a.startswith('--bury-siblings'):
                v,i=parse_value(args,i,'--bury-siblings')
                if v not in ('true','false'):
                    print(f"error: invalid value '{v}' for '--bury-siblings <BURY_SIBLINGS>'\n  [possible values: true, false]\n\nFor more information, try '--help'.", file=sys.stderr); return 2
            else: directory=a
            i+=1
        cmd_drill(directory or os.getcwd(), opts); return 0
    print(f"error: unrecognized subcommand '{cmd}'\n\nUsage: executable <COMMAND>\n\nFor more information, try '--help'.", file=sys.stderr); return 2

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
